/**
 * @file algorithm_template_traits.hpp
 * @brief The conformance-kit traits of algorithm_template, a hypergraph algorithm (PLAN Section
 *        8.2; the kit's hypergraph axis, ADR 0043; generated by scripts/new_algorithm.py
 *        --container hypergraph).
 */
#pragma once

#include "conformance/hypergraph_generators.hpp"
#include "conformance/test_traits.hpp"
#include "conformance/type_list.hpp"

#include <dyng/algorithm_template.hpp>
#include <dyng/core/backend.hpp>
#include <dyng/core/copy.hpp>
#include <dyng/core/resources.hpp>
#include <dyng/core/types.hpp>
#include <dyng/hypergraph/hyperedge_batch.hpp>
#include <dyng/hypergraph/hypergraph.hpp>
#include <dyng/hypergraph/hypergraph_properties.hpp>

#include <cstdint>
#include <functional>
#include <string_view>
#include <vector>

namespace dyng::conformance {

/// algorithm_template (TODO(algorithm_template): what the kit compares).
template <>
struct test_traits<tags::algorithm_template> {
  static constexpr std::string_view name = "algorithm_template";  ///< as in the manifest
  static constexpr oracle_kind oracle = oracle_kind::compute;     ///< update chain == compute
  static constexpr determinism level = determinism::exact_value;  ///< identical values
  static constexpr bool history_independent = true;               ///< the result of a hypergraph
  /// The instantiated hypergraph types (DYNG_FOR_EACH_HYPERGRAPH_TYPE).
  using container_types =
      type_list<hypergraph<std::int32_t, unweighted>, hypergraph<std::int32_t, std::int32_t>>;
  template <typename container_t>
  using result = algorithm_template::result;   ///< the result
  using stats = algorithm_template::stats;     ///< update()'s stats
                                               //@@ fixed_point
  using snapshot = std::vector<std::int32_t>;  ///< the labels
                                               //@@ end
                                               //@@ aggregate_delta
  using snapshot = std::uint64_t;              ///< the count
                                               //@@ end

  /// The hypergraph requirements (the manifest's graph_requirements; the kit's presets add the
  /// id_reuse orders and the capacity presets).
  static void require(hypergraph_properties& props) {
    (void)props;
  }
  /// The generated hypergraphs (the medium one has more than 1,024 vertices, so the kit's skewed
  /// mix inserts a hyperedge of more than 1,024 members).
  static hypergraph_shape shape(size_class size) {
    switch (size) {
      case size_class::tiny:
        return {6, 4, 3, 9};
      case size_class::small:
        return {40, 30, 5, 9};
      case size_class::medium:
        return {1100, 300, 8, 9};
    }
    return {};
  }
  /// compute() (one engine).
  template <typename container_t>
  static result<container_t> compute(const resources& res, const container_t& h, engine /*e*/) {
    return algorithm_template::compute(res, h);
  }
  /// update().
  template <typename container_t>
  static stats update(const resources& res, container_t& h,
                      const typename container_t::batch_view_type& batch, result<container_t>& r) {
    return algorithm_template::update(res, h, batch, r);
  }
  /// The result on the host.
  template <typename container_t>
  static snapshot take(const resources& res, const result<container_t>& r) {
    //@@ fixed_point
    return to_vector(res, r.labels());
    //@@ end
    //@@ aggregate_delta
    (void)res;
    return r.count();
    //@@ end
  }
  /// The counters that are equal across runs and backends (besides the common ones).
  static std::vector<std::int64_t> deterministic(const stats& /*s*/) {
    return {};
  }
  /// Options and hypergraphs compute() and set_options() reject (TODO(algorithm_template)).
  template <typename container_t>
  static std::vector<std::function<void()>> invalid_options(const resources& /*res*/,
                                                            const container_t& /*h*/) {
    return {};
  }
  /// C8: host synchronizations of the algorithm phase (none: host backends only).
  static std::int64_t host_sync_budget(backend /*b*/) {
    return 0;
  }
};

}  // namespace dyng::conformance
